/// <summary>
/// Synthetic class of the test data, with label IDs in code.
/// </summary>
internal final class BDMDeliveryHelper
{
}

Method.Source:
public static str caption()
{
    return strFmt("%1 %2", "@BDM1:BDM110000003", "@SYS12345");
}

public static str legacyCaption()
{
    // Single quotes, which the existing tool turns into double quotes when replacing.
    return '@BDM1:BDM110000003' + literalStr(@SYS123456);
}
